Record pfH (mem : word -> option byte) (sp : word) (w can : Z) : Prop := PFH {
  Psp16  : bv_unsigned sp mod 16 = 0;
  PspLo  : 0x12d420 <= bv_unsigned sp;
  PspHi  : bv_unsigned sp <= 0x7fffffffffff;
  Pstk   : stk_ok RSEGS mem sp PF_FR;
  Pimg   : forall i, 0x10000 <= i < 0xf1000 -> mem (Z_to_bv 64 i) = None;   (* [comment removed for export] *)
  Pgot   : rdn RSEGS mem (Z_to_bv 64 0xf8770) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0x12b6f8)); (* [comment removed for export] *)
  Pflags : rdn RSEGS mem (Z_to_bv 64 0xf9a98) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 5));
  Pwend  : rdn RSEGS mem (Z_to_bv 64 0xf9ab8) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0x12c2a8));
  Pwpos  : rdn RSEGS mem (Z_to_bv 64 0xf9ac0) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 w));
  Pw     : 0x12bea8 <= w <= 0x12c2a6;
  Pbsz   : rdn RSEGS mem (Z_to_bv 64 0xf9af8) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 1024));
  Plock  : rdn RSEGS mem (Z_to_bv 64 0xf9b24) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 4294967295));
  Plbf   : rdn RSEGS mem (Z_to_bv 64 0xf9b28) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 4294967295));
  Pcan   : rdn RSEGS mem (Z_to_bv 64 0x12b6f8) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 can));
  Pcan64 : 0 <= can < 2 ^ 64 }.

